            parts = line.strip().split('\t')
            if len(parts) == 2:
                try:
                    coord = int(parts[1])
                    coords.append(coord)
                except:
                    continue
    return coords

def find_flag(coords):
    # Calculate differences between consecutive values
    diffs = []
    for i in range(1, len(coords)):
        diff = coords[i] - coords[i-1]
        diffs.append(diff)

    # Convert differences to ASCII (try different multipliers)
    multipliers = [1, 10, 100]
    for mult in multipliers:
        print(f"\nTrying multiplier {mult}:")
        chars_list = []
        for diff in diffs:
            try:
                # Try both positive and negative differences
                val = abs(diff * mult)
                if 32 <= val <= 126:  # printable ASCII range
                    chars_list.append(chr(val))
            except:
                continue

        message = ''.join(chars_list)
        print(f"Message: {message}")

        # Look for flag pattern
        if 'flag{' in message:
            start = message.find('flag{')
            end = message.find('}', start)
            if end != -1:
                flag = message[start:end+1]
                print(f"\nPossible flag found: {flag}")

    # Also try the raw coordinates
    print("\nTrying raw coordinates:")
    chars_from_coords = []
    for coord in coords:
        if 32 <= coord <= 126:
            chars_from_coords.append(chr(coord))

    coord_message = ''.join(chars_from_coords)
    print(f"Message from raw coordinates: {coord_message}")

