import struct

def process_coordinates(filename):
    coords = []
    with open(filename, 'r') as f:
        for line in f:
            try:
                # Convert hex string to bytes and unpack as float
                data = bytes.fromhex(line.strip())
                # Try different positions in the data for coordinates
                for i in range(0, len(data)-7, 8):
                    try:
                        value = struct.unpack('d', data[i:i+8])[0]
                        if -180 <= value <= 180:  # Valid coordinate range
                            coords.append(value)
                    except:
                        continue
            except:
                continue

    # Process differences
    if len(coords) > 1:
        diffs = []
        for i in range(1, len(coords)):
            diff = coords[i] - coords[i-1]
            ascii_val = int(abs(diff * 10))
            if 32 <= ascii_val <= 126:  # Printable ASCII range
                diffs.append(ascii_val)

        # Convert to characters
        print("ASCII values:", diffs)
        chars = ''.join(chr(x) for x in diffs)
        print("Decoded string:", chars)

if __name__ == "__main__":
    process_coordinates("coordinates.txt")

