from scapy.all import *

def extract_coordinates(pcap_file):
    packets = rdpcap(pcap_file)
    coords = []

    for pkt in packets:
        if Raw in pkt:
            raw_data = bytes(pkt[Raw])
            try:
                # Try to find all possible float values in the data
                for i in range(0, len(raw_data)-7, 8):
                    try:
                        value = struct.unpack('d', raw_data[i:i+8])[0]
                        if -180 <= value <= 180:  # Valid coordinate range
                            coords.append(value)
                    except:
                        continue
            except:
                continue

    return coords

def process_differences(coords):
    if len(coords) < 2:
        return

    print(f"Found {len(coords)} coordinates")
    print("First few coordinates:", coords[:5])

    # Calculate differences
    diffs = []
    for i in range(1, len(coords)):
        diff = coords[i] - coords[i-1]
        ascii_val = int(abs(diff * 10))
        if 32 <= ascii_val <= 126:  # Printable ASCII range
            diffs.append(ascii_val)

    print("\nFound differences (as ASCII):", diffs[:20])

    # Convert to string
    chars = ''.join(chr(x) for x in diffs)
    print("\nDecoded string (first 100 chars):", chars[:100])

    # Look for flag pattern
    if 'flag{' in chars:
        start = chars.index('flag{')
        end = chars.index('}', start) + 1
        print("\nFound flag:", chars[start:end])

